    const toTitleCaseFileName = (fileName) => {
      if (!fileName.endsWith('.html')) return fileName;
      const name = fileName.substring(0, fileName.length - 5);
      const titleCase = name
        .split('-')
        .map((part) => part ? part.charAt(0).toUpperCase() + part.slice(1) : part)
        .join('-');
      return titleCase + '.html';
    };

    async function navigateWithFallback(event, canonicalFile) {
      if (event) event.preventDefault();

      const candidates = [canonicalFile];
      const titleCase = toTitleCaseFileName(canonicalFile);
      if (titleCase !== canonicalFile) candidates.push(titleCase);

      for (const file of candidates) {
        try {
          const response = await fetch('./' + file, { method: 'HEAD', cache: 'no-store' });
          if (response.ok) {
            window.location.href = './' + file;
            return false;
          }
        } catch (_) {
          // try next candidate
        }
      }

      window.location.href = './' + canonicalFile;
      return false;
    }
